import React, { useEffect, useMemo, useState } from "react";
import axios from "axios";
import {
  Alert,
  AppBar,
  Badge,
  Box,
  Button,
  Card,
  CardContent,
  CardMedia,
  Chip,
  Container,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  Grid,
  IconButton,
  InputAdornment,
  MenuItem,
  Paper,
  Snackbar,
  TextField,
  Toolbar,
  Typography,
} from "@mui/material";

import {
  Add,
  Remove,
  Search,
  ShoppingCart,
  Logout,
  Restaurant,
} from "@mui/icons-material";

const categories = [
  "All",
  "Breakfast",
  "Lunch",
  "Snacks",
  "Beverages",
  "Desserts",
  "Other",
];

const UserDashboard = ({ user, onLogout }) => {
  const [menuItems, setMenuItems] = useState([]);
  const [cart, setCart] = useState([]);

  const [selectedCategory, setSelectedCategory] = useState("All");
  const [search, setSearch] = useState("");

  const [loadingMenu, setLoadingMenu] = useState(true);

  const [cartOpen, setCartOpen] = useState(false);

  const [snackbar, setSnackbar] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  /*
  ==================================================
  GET MENU FROM MONGODB
  ==================================================
  */

  const fetchMenu = async () => {
    try {
      setLoadingMenu(true);

      const response = await axios.get("/api/menu");

      setMenuItems(response.data.menuItems || []);
    } catch (error) {
      console.error("Failed to fetch menu:", error);

      showSnackbar(
        error.response?.data?.message || "Failed to load menu",
        "error"
      );
    } finally {
      setLoadingMenu(false);
    }
  };

  useEffect(() => {
    fetchMenu();
  }, []);

  /*
  ==================================================
  SNACKBAR
  ==================================================
  */

  const showSnackbar = (message, severity = "success") => {
    setSnackbar({
      open: true,
      message,
      severity,
    });
  };

  const closeSnackbar = () => {
    setSnackbar((prev) => ({
      ...prev,
      open: false,
    }));
  };

  /*
  ==================================================
  FILTER MENU
  ==================================================
  */

  const filteredMenu = useMemo(() => {
    return menuItems.filter((item) => {
      const matchesCategory =
        selectedCategory === "All" ||
        item.category === selectedCategory;

      const matchesSearch = item.name
        .toLowerCase()
        .includes(search.toLowerCase());

      return matchesCategory && matchesSearch;
    });
  }, [menuItems, selectedCategory, search]);

  /*
  ==================================================
  CART HELPERS
  ==================================================
  */

  const addToCart = (item) => {
    if (!item.available) {
      showSnackbar(`${item.name} is currently unavailable`, "error");
      return;
    }

    if (item.stock <= 0) {
      showSnackbar(`${item.name} is out of stock`, "error");
      return;
    }

    setCart((prevCart) => {
      const existingItem = prevCart.find(
        (cartItem) => cartItem.menuItemId === item._id
      );

      if (existingItem) {
        if (existingItem.quantity >= item.stock) {
          showSnackbar(
            `Only ${item.stock} ${item.name} available`,
            "warning"
          );

          return prevCart;
        }

        return prevCart.map((cartItem) =>
          cartItem.menuItemId === item._id
            ? {
              ...cartItem,
              quantity: cartItem.quantity + 1,
            }
            : cartItem
        );
      }

      return [
        ...prevCart,
        {
          menuItemId: item._id,
          name: item.name,
          price: item.price,
          image: item.image || "",
          quantity: 1,
          stock: item.stock,
        },
      ];
    });

    showSnackbar(`${item.name} added to cart`);
  };

  const increaseQuantity = (menuItemId) => {
    setCart((prevCart) =>
      prevCart.map((item) => {
        if (item.menuItemId !== menuItemId) {
          return item;
        }

        if (item.quantity >= item.stock) {
          showSnackbar(
            `Only ${item.stock} ${item.name} available`,
            "warning"
          );

          return item;
        }

        return {
          ...item,
          quantity: item.quantity + 1,
        };
      })
    );
  };

  const decreaseQuantity = (menuItemId) => {
    setCart((prevCart) =>
      prevCart
        .map((item) => {
          if (item.menuItemId !== menuItemId) {
            return item;
          }

          return {
            ...item,
            quantity: item.quantity - 1,
          };
        })
        .filter((item) => item.quantity > 0)
    );
  };

  /*
  ==================================================
  CART TOTALS
  ==================================================
  */

  const cartCount = cart.reduce(
    (total, item) => total + item.quantity,
    0
  );

  const cartTotal = cart.reduce(
    (total, item) => total + item.price * item.quantity,
    0
  );

  /*
  ==================================================
  ORDER
  ==================================================
  */

  const placeOrder = async () => {
    if (cart.length === 0) {
      showSnackbar("Your cart is empty", "error");
      return;
    }

    try {
      const token = localStorage.getItem("token");

      const response = await axios.post(
        "/api/orders",
        {
          items: cart.map((item) => ({
            menuItemId: item.menuItemId,
            quantity: item.quantity,
          })),
          paymentMethod: "Cash",
          specialRequests: "",
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      const order = response.data.order;

      setCart([]);
      setCartOpen(false);

      showSnackbar(
        `Order placed successfully. Token: ${order.orderNumber}`,
        "success"
      );

      /*
      Refresh menu so updated stock is displayed
      */

      await fetchMenu();
    } catch (error) {
      console.error("Place order error:", error);

      showSnackbar(
        error.response?.data?.message || "Failed to place order",
        "error"
      );
    }
  };

  /*
  ==================================================
  LOGOUT
  ==================================================
  */

  const handleLogout = () => {
    onLogout();
  };

  return (
    <Box
      sx={{
        minHeight: "100vh",
        backgroundColor: "#f5f7f5",
      }}
    >
      {/* ================= HEADER ================= */}

      <AppBar
        position="sticky"
        elevation={0}
        sx={{
          backgroundColor: "#1b5e20",
        }}
      >
        <Toolbar>
          <Restaurant sx={{ mr: 1 }} />

          <Typography
            variant="h6"
            sx={{
              fontWeight: 700,
              flexGrow: 1,
            }}
          >
            CanteenPro
          </Typography>

          <Typography
            sx={{
              mr: 2,
              display: {
                xs: "none",
                sm: "block",
              },
            }}
          >
            Hi, {user?.name}
          </Typography>

          <IconButton
            color="inherit"
            onClick={() => setCartOpen(true)}
          >
            <Badge
              badgeContent={cartCount}
              color="error"
            >
              <ShoppingCart />
            </Badge>
          </IconButton>

          <Button
            color="inherit"
            startIcon={<Logout />}
            onClick={handleLogout}
            sx={{
              ml: 1,
            }}
          >
            Logout
          </Button>
        </Toolbar>
      </AppBar>

      {/* ================= CONTENT ================= */}

      <Container
        maxWidth="xl"
        sx={{
          py: 4,
        }}
      >
        <Typography
          variant="h4"
          sx={{
            fontWeight: 700,
            mb: 1,
          }}
        >
          Welcome, {user?.name}
        </Typography>

        <Typography
          color="text.secondary"
          sx={{
            mb: 3,
          }}
        >
          Choose your favourite food and place your order.
        </Typography>

        {/* ================= SEARCH ================= */}

        <TextField
          fullWidth
          placeholder="Search food..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          sx={{
            mb: 3,
            backgroundColor: "white",
          }}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <Search />
              </InputAdornment>
            ),
          }}
        />

        {/* ================= CATEGORIES ================= */}

        <Box
          sx={{
            display: "flex",
            gap: 1,
            flexWrap: "wrap",
            mb: 4,
          }}
        >
          {categories.map((category) => (
            <Chip
              key={category}
              label={category}
              clickable
              color={
                selectedCategory === category
                  ? "success"
                  : "default"
              }
              onClick={() => setSelectedCategory(category)}
            />
          ))}
        </Box>

        {/* ================= MENU ================= */}

        {loadingMenu ? (
          <Box
            sx={{
              textAlign: "center",
              py: 8,
            }}
          >
            <Typography>
              Loading menu...
            </Typography>
          </Box>
        ) : filteredMenu.length === 0 ? (
          <Paper
            sx={{
              p: 6,
              textAlign: "center",
            }}
          >
            <Restaurant
              sx={{
                fontSize: 60,
                color: "text.secondary",
                mb: 2,
              }}
            />

            <Typography variant="h6">
              No food items found
            </Typography>

            <Typography
              color="text.secondary"
              sx={{
                mt: 1,
              }}
            >
              Admin has not added food items in this category yet.
            </Typography>
          </Paper>
        ) : (
          <Grid
            container
            spacing={3}
          >
            {filteredMenu.map((item) => {
              const outOfStock =
                item.stock <= 0 || !item.available;

              return (
                <Grid
                  item
                  xs={12}
                  sm={6}
                  md={4}
                  lg={3}
                  key={item._id}
                >
                  <Card
                    sx={{
                      height: "100%",
                      display: "flex",
                      flexDirection: "column",
                      borderRadius: 3,
                      overflow: "hidden",
                    }}
                  >
                    {item.image ? (
                      <CardMedia
                        component="img"
                        height="200"
                        image={item.image}
                        alt={item.name}
                        sx={{
                          objectFit: "cover",
                        }}
                      />
                    ) : (
                      <Box
                        sx={{
                          height: 200,
                          backgroundColor: "#e8f5e9",
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center",
                        }}
                      >
                        <Restaurant
                          sx={{
                            fontSize: 70,
                            color: "#66bb6a",
                          }}
                        />
                      </Box>
                    )}

                    <CardContent
                      sx={{
                        flexGrow: 1,
                      }}
                    >
                      <Box
                        sx={{
                          display: "flex",
                          justifyContent: "space-between",
                          alignItems: "center",
                          mb: 1,
                        }}
                      >
                        <Typography
                          variant="h6"
                          sx={{
                            fontWeight: 700,
                          }}
                        >
                          {item.name}
                        </Typography>

                        <Chip
                          label={item.category}
                          size="small"
                          color="success"
                          variant="outlined"
                        />
                      </Box>

                      <Typography
                        color="text.secondary"
                        sx={{
                          minHeight: 48,
                          mb: 2,
                        }}
                      >
                        {item.description}
                      </Typography>

                      <Typography
                        variant="h6"
                        sx={{
                          fontWeight: 700,
                          color: "#1b5e20",
                          mb: 1,
                        }}
                      >
                        ₹{item.price}
                      </Typography>

                      <Typography
                        variant="body2"
                        color={
                          outOfStock
                            ? "error"
                            : "text.secondary"
                        }
                        sx={{
                          mb: 2,
                        }}
                      >
                        {outOfStock
                          ? !item.available
                            ? "Currently unavailable"
                            : "Out of stock"
                          : `${item.stock} available`}
                      </Typography>

                      <Button
                        fullWidth
                        variant="contained"
                        color="success"
                        startIcon={<ShoppingCart />}
                        disabled={outOfStock}
                        onClick={() => addToCart(item)}
                      >
                        {outOfStock
                          ? "Unavailable"
                          : "Add to Cart"}
                      </Button>
                    </CardContent>
                  </Card>
                </Grid>
              );
            })}
          </Grid>
        )}
      </Container>

      {/* ================= CART DIALOG ================= */}

      <Dialog
        open={cartOpen}
        onClose={() => setCartOpen(false)}
        fullWidth
        maxWidth="sm"
      >
        <DialogTitle>
          Your Cart
        </DialogTitle>

        <DialogContent>
          {cart.length === 0 ? (
            <Box
              sx={{
                py: 5,
                textAlign: "center",
              }}
            >
              <ShoppingCart
                sx={{
                  fontSize: 60,
                  color: "text.secondary",
                }}
              />

              <Typography
                variant="h6"
                sx={{
                  mt: 2,
                }}
              >
                Your cart is empty
              </Typography>
            </Box>
          ) : (
            <>
              {cart.map((item) => (
                <Box
                  key={item.menuItemId}
                  sx={{
                    py: 2,
                  }}
                >
                  <Box
                    sx={{
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center",
                    }}
                  >
                    <Box>
                      <Typography
                        sx={{
                          fontWeight: 600,
                        }}
                      >
                        {item.name}
                      </Typography>

                      <Typography
                        color="text.secondary"
                      >
                        ₹{item.price} × {item.quantity}
                      </Typography>
                    </Box>

                    <Box
                      sx={{
                        display: "flex",
                        alignItems: "center",
                      }}
                    >
                      <IconButton
                        size="small"
                        onClick={() =>
                          decreaseQuantity(
                            item.menuItemId
                          )
                        }
                      >
                        <Remove />
                      </IconButton>

                      <Typography
                        sx={{
                          mx: 1,
                          fontWeight: 600,
                        }}
                      >
                        {item.quantity}
                      </Typography>

                      <IconButton
                        size="small"
                        onClick={() =>
                          increaseQuantity(
                            item.menuItemId
                          )
                        }
                      >
                        <Add />
                      </IconButton>
                    </Box>
                  </Box>

                  <Divider sx={{ mt: 2 }} />
                </Box>
              ))}

              <Box
                sx={{
                  display: "flex",
                  justifyContent: "space-between",
                  mt: 2,
                }}
              >
                <Typography
                  variant="h6"
                  sx={{
                    fontWeight: 700,
                  }}
                >
                  Total
                </Typography>

                <Typography
                  variant="h6"
                  sx={{
                    fontWeight: 700,
                    color: "#1b5e20",
                  }}
                >
                  ₹{cartTotal}
                </Typography>
              </Box>
            </>
          )}
        </DialogContent>

        <DialogActions
          sx={{
            p: 2,
          }}
        >
          <Button
            onClick={() => setCartOpen(false)}
          >
            Close
          </Button>

          <Button
            variant="contained"
            color="success"
            disabled={cart.length === 0}
            onClick={placeOrder}
          >
            Place Order
          </Button>
        </DialogActions>
      </Dialog>

      {/* ================= SNACKBAR ================= */}

      <Snackbar
        open={snackbar.open}
        autoHideDuration={4000}
        onClose={closeSnackbar}
        anchorOrigin={{
          vertical: "bottom",
          horizontal: "center",
        }}
      >
        <Alert
          onClose={closeSnackbar}
          severity={snackbar.severity}
          variant="filled"
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default UserDashboard;
